import {$,api,post,message,button} from './common.js?v=6.19.0';
let me;
function showLink(result){$('inviteLink').value=result.url;$('inviteResult').hidden=false;message(`Lien créé pour ${result.username}. Il expire dans sept jours.`);$('inviteResult').scrollIntoView({behavior:'smooth',block:'center'});}
async function refresh(){const [users,invites]=await Promise.all([api('/api/admin/users'),api('/api/admin/invitations')]);$('users').replaceChildren();for(const u of users){const row=document.createElement('div'),name=document.createElement('strong');row.className='managementrow';name.textContent=`${u.username} · ${u.is_admin?'admin':'membre'} · ${u.active?'actif':'désactivé'}`;row.append(name);if(u.id!==me.id){row.append(button(u.active?'Désactiver':'Réactiver',async()=>{await api(`/api/admin/users/${u.id}`,{method:'PATCH',body:JSON.stringify({active:!u.active,isAdmin:u.is_admin})});await refresh();}),button(u.is_admin?'Retirer admin':'Nommer admin',async()=>{if(!confirm('Modifier les droits de '+u.username+' ?'))return;await api(`/api/admin/users/${u.id}`,{method:'PATCH',body:JSON.stringify({active:u.active,isAdmin:!u.is_admin})});await refresh();}),button('Supprimer',async()=>{if(!confirm(`Supprimer définitivement ${u.username} et toutes ses données ?`))return;await api(`/api/admin/users/${u.id}`,{method:'DELETE'});await refresh();}));}if(u.active)row.append(button('Lien de réinitialisation',async()=>{const result=await post(`/api/admin/users/${u.id}/reset`,{});showLink(result);await refresh();}));$('users').append(row);}
 $('invitations').replaceChildren();for(const inv of invites){const row=document.createElement('div'),text=document.createElement('span');row.className='managementrow';const state=inv.used_at?'utilisée':inv.revoked_at?'révoquée':new Date(inv.expires_at)<new Date()?'expirée':'en attente';text.textContent=`${inv.username} · ${state} · ${new Date(inv.expires_at).toLocaleDateString('fr')}`;row.append(text);if(state==='en attente')row.append(button('Révoquer',async()=>{await api(`/api/admin/invitations/${inv.id}`,{method:'DELETE'});await refresh();}));$('invitations').append(row);}}
$('inviteForm').onsubmit=async e=>{e.preventDefault();try{showLink(await post('/api/admin/invitations',{username:$('inviteUsername').value}));$('inviteForm').reset();await refresh();}catch(e){message(e.message);}};
$('copyLink').onclick=async()=>{try{await navigator.clipboard.writeText($('inviteLink').value);message('Lien copié.');}catch{$('inviteLink').select();message('Copiez le lien sélectionné.');}};
try{me=await api('/api/me');if(!me.isAdmin)throw Error('Accès réservé à l’administrateur.');await refresh();const database=await api('/api/admin/database');$('databaseStatus').textContent=`${database.version} · ${database.rides} sortie(s) et ${database.portions} secteur(s), ${database.plans} itinéraire(s) géographiques.`;}catch(e){message(e.message);}
